SELECT ROUND(AVG(lng), 5) AS lng, ROUND(AVG(lat), 5) AS lat, COUNT(*) AS count
FROM post
WHERE status = 'active' AND expire_at > NOW()

    AND grid_id IN
    #{g}

AND leaf_category_id IN
#{c}
AND type = #{type}
GROUP BY grid_id
LIMIT #{limit}

SELECT p.id, p.type, p.leaf_category_id, p.l2_category_id, p.title, p.`desc` AS summary, p.lng, p.lat, p.completeness_level, p.created_at AS publish_at, u.id AS author_id, u.nickname, u.avatar_url, u.realname_status FROM post p JOIN user u ON p.user_id = u.id WHERE p.status = 'active' AND p.expire_at > NOW()
AND p.grid_id IN #{g}
AND p.leaf_category_id IN #{c} AND p.type = #{type}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.`desc` LIKE CONCAT('%', #{keyword}, '%'))
